DROP TABLE IF EXISTS `residents`;
CREATE TABLE `residents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `first_name` varchar(50) NOT NULL,
  `middle_name` varchar(50) DEFAULT '',
  `last_name` varchar(50) NOT NULL,
  `date_of_birth` date DEFAULT '2000-01-01',
  `gender` varchar(20) DEFAULT 'Male',
  `civil_status` varchar(50) DEFAULT 'Single',
  `address` varchar(255) NOT NULL,
  `purok` varchar(50) DEFAULT '1',
  `barangay` varchar(100) DEFAULT 'Pianing',
  `city` varchar(100) DEFAULT 'Butuan City',
  `phone` varchar(20) DEFAULT '',
  `email` varchar(100) DEFAULT '',
  `employment_status` varchar(50) DEFAULT 'Employed',
  `submitted_id` longtext DEFAULT NULL,
  `id_type` varchar(100) DEFAULT 'Government ID',
  `submitted_at` datetime DEFAULT current_timestamp(),
  `claimed_at` datetime DEFAULT NULL,
  `linked_user_id` int(11) DEFAULT NULL,
  `household_number` varchar(50) DEFAULT NULL,
  `family_name` varchar(100) DEFAULT NULL,
  `is_head_of_household` tinyint(1) DEFAULT 0,
  `relationship_to_head` varchar(50) DEFAULT 'Member',
