DROP TABLE IF EXISTS `sms_notifications`;
CREATE TABLE `sms_notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `recipient_name` varchar(100) NOT NULL,
  `recipient_phone` varchar(20) NOT NULL,
